    return 1 - (sum_j (m_j^3 - m_j)) / (n^3 - n)          # exact rationals

function CAPPED_PROFILE(K, r, base p):
    top <- p^r                                            # merged class {v_p >= K}
    resolved <- [ (p-1) * p^(r+i) for i in 0..K-1 ]        # exact valuation i
    return [top] ++ resolved

function CAPPED_CEILING_CLOSED_FORM(K, r, base p):
    b <- r + K;  require b >= 1
    if K = 0: return 0                                     # one giant tie class
    L <- 3p / (p^2 + p + 1)
    return L * (p^(3b) - p^(3r)) / (p^(3b) - p^b)

function UNIVERSAL_CAPPED_FLOOR(base p):
    L <- 3p / (p^2 + p + 1)
    return L * (1 - p^(-3))                                # = 3/4 when p = 2

function EXCLUSION_REPORT(reading rho, base p):
    floor <- UNIVERSAL_CAPPED_FLOOR(p)
    excluded <- (rho^2 < floor)
    return { rho, rho^2, floor, excluded, margin = floor / rho^2 }

