constants FLOOR = 11/20,  FLOOR_BUDGET = 3/40

function REQUIRED_FRACTION(rho):
    return (1 - rho) / 6            # from 1 - rho <= 6|A|/n

function FORCED_DISPLACEMENT(rho, n):
    return ceil( n * REQUIRED_FRACTION(rho) )

function SAFE_FOOTPRINT(n):
    return floor( n * FLOOR_BUDGET )

function LEDGER(rho, n):
    f <- REQUIRED_FRACTION(rho)
    return { reading      = rho,
             forced_frac  = f,
             forced_pts   = ceil(n*f),
             safe_pts     = floor(n*FLOOR_BUDGET),
             in_band      = (rho >= FLOOR),
             over_budget  = (f > FLOOR_BUDGET) }

function CERTIFY_FLOOR(n, touched):
    guaranteed <- 1 - 6*touched/n   # worst-case reading after the disturbance
    return ( touched/n <= FLOOR_BUDGET , guaranteed )

function L(p):
    return 3p / (p^2 + p + 1)

function EFFECTIVE_BASE(rho):
    t <- rho^2
    if t <= 0 or t > L(2): return NONE          # outside the dial's range
    p <- max(2, ceil(3/t) - 2)                  # seed from L(p) ~ 3/p
    loop:
        if L(p+1) < t <= L(p): return p
        if t > L(p): p <- p - 1                 # reading too strong: smaller base
        else:        p <- p + 1                 # reading too weak: larger base

function RHO_MODEL(b):
    return 5/14 + 93/(5b)                       # fitted hyperbolic erosion law

function DRIFT_TABLE(bitlens):
    for b in bitlens:
        rho <- RHO_MODEL(b)
        emit ( b, rho, rho^2, EFFECTIVE_BASE(rho) )

